export function monsterArt(id, evolved = false) {
  const shape = faces[id] || faces.medamago;
  return `<svg viewBox="0 0 180 164" class="monster-svg ${evolved ? 'monster-evolved' : ''}" role="img" aria-label="モンスターのイラスト" xmlns="http://www.w3.org/2000/svg">${evolved ? '<path d="M35 37L23 18M144 38L157 20M91 16V3" stroke="#f2b64b" stroke-width="6" stroke-linecap="round"/>' : ''}${shape}</svg>`;
}
